input.command:
cd /home/user/rork-app && echo "=== Query Render deploys directly ===" && curl -s -H "Authorization: Bearer $RENDER_API_KEY" "https://api.render.com/v1/services/$RENDER_SERVICE_ID/deploys?limit=5" -o /tmp/deploys.json && node -e "
const r=require('/tmp/deploys.json');
if (!Array.isArray(r)) { console.log(JSON.stringify(r).slice(0,500)); process.exit(); }
r.forEach(d => console.log({
  id: d.id, commit: d.commit && d.commit.id, status: d.status, createdAt: d.createdAt, finishedAt: d.finishedAt, updatedAt: d.updatedAt
}));"

